 "content": "def transform(grid):
    """Count horizontal object-runs of colors 3 and 2, packed into a 2x3 grid."""
    counts = {3: 0, 2: 0}
    for row in grid:
        i = 0
        while i < len(row):
            color = row[i]
            if color in counts:
                counts[color] += 1
                while i < len(row) and row[i] == color:
                    i += 1
            else:
                i += 1
    values = [3] * counts[3] + [2] * counts[2]
    values = (values + [0] * 6)[:6]
    return [values[:3], values[3:]]
